const POLAR_NATIVE_PREFIX='HERO-003 / Current original / '
function polarFind(root:HTMLElement|null,key:string){return root?.querySelector<HTMLElement>(`[id="${key}"]`)??root?.querySelector<HTMLElement>(`[data-framer-name="${POLAR_NATIVE_PREFIX+key}"]`)??null}
function polarKey(host:HTMLElement,prefix=''){const name=host.id||host.getAttribute('data-framer-name')?.replace(POLAR_NATIVE_PREFIX,'')||'';return name.startsWith(prefix)?name.slice(prefix.length):name}
const POLAR_ACTORS=["run_7f2","run_91c","agent_ada","run_b03","key_live_4"]
const polarClamp=(n:number,a=0,b=1)=>Math.max(a,Math.min(b,Number.isFinite(n)?n:a))
function polarRandom(seed:number){let state=seed>>>0;return()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296}}
function polarAppend(model:PolarModel,kind:PolarEventKind,quantity:number,actor:string):PolarModel{const n=model.head+1,balance=kind==="credit.granted"?model.balance+quantity:model.balance-(kind==="llm.completion"?quantity:0),event={n,kind,quantity,actor,balance};return{...model,head:n,balance,tokens:model.tokens+(kind==="llm.completion"?quantity:0),events:[...model.events,event].slice(-64)}}
function polarNext(model:PolarModel,random:()=>number){const choose=random(),kind:PolarEventKind=choose<.72?"llm.completion":choose<.88?"api.call":"image.gen",quantity=kind==="llm.completion"?120+Math.floor(random()*1400):kind==="image.gen"?1+Math.floor(random()*3):1,actor=POLAR_ACTORS[Math.floor(random()*POLAR_ACTORS.length)];let next=model;if(kind==="llm.completion"&&model.balance<quantity)next=polarAppend(next,"credit.granted",model.grant,"polar");return polarAppend(next,kind,quantity,actor)}
function polarInitial(random:()=>number){let model:PolarModel={head:0,events:[],tokens:0,balance:0,grant:10000};for(let i=0;i<12;i++)model=polarNext(model,random);return model}
interface PolarWorld {members:Set<symbol>;admit:(id:symbol,active:boolean)=>void;nav:PolarNav;model:PolarModel;scroller:HTMLElement|null;root:HTMLElement|null;seen:Set<string>;animations:Set<Animation>;subscribe:(channel:"nav"|"model"|"layout",fn:()=>void)=>()=>void;setScroller:(host:HTMLElement|null)=>void;configure:(enabled:boolean,reduced:boolean)=>void;hover:(n:number|null)=>void;activate:(id:string)=>void;chapter:(id:string)=>void;reconcile:()=>void;toggle:()=>void;step:()=>void;reset:()=>void;animate:(animation:Animation)=>void;stop:()=>void;debug:()=>{timer:boolean;listeners:number;animations:number;events:number}}
const POLAR_CANVAS_ANIMATIONS=new WeakMap<Animation,{started:number;duration:number;finished:boolean;pausedAt:number|null}>()
